export function agentBudget(
  deadlineAt: number,
  now: number,
  minBudgetSecs: number,
): { budget: number; floored: boolean } {
  const left = Math.floor(deadlineAt - now);
  if (left < minBudgetSecs) return { budget: minBudgetSecs, floored: true };
